5	import {
6	  PlaybackState,
7	  secondsToTicks,
8	  toTick,
9	  type AssetId,
10	  type AssetType,
11	  type TrackId,
12	  type TrackItemId,
13	} from "@motion-studio/shared";
14	import { useEditorKernel } from "./editor-kernel-provider";
15	import { ToolbarPanel } from "./toolbar/toolbar-panel";
16	import { CanvasPanel } from "./canvas/canvas-panel";
17	import { PlaybackBar } from "./canvas/playback-bar";
18	import { TimelinePanel } from "./timeline/timeline-panel";
19	import { InspectorPanel } from "./inspector/inspector-panel";
20	import { IconRail } from "./rail/icon-rail";
21	import { LeftPanel } from "./rail/left-panel";
22	import { useTimelineStore } from "../state/use-timeline-store";
23	import { useCanvasStore } from "../state/use-canvas-store";
24	import type { EditorKernel } from "../editor-kernel/editor-kernel";
25	
26	const DEFAULT_CLIP_DURATION_SECONDS = 3;
27	
28	type DragData =
29	  | { type: "asset"; assetId: AssetId; assetType: AssetType; name: string }
30	  | { type: "clip"; trackItemId: TrackItemId };
31	
32	type DropData = { type: "track"; trackId: TrackId };
33	
34	/**
35	 * Handles both drop targets a Timeline track accepts: a freshly dragged
36	 * Asset Browser tile (creates a Layer + TrackItem via
37	 * `TimelineEditorService.addClipFromAsset`) and an existing clip being
38	 * repositioned (`moveTrackItem`). One `DndContext` at the shell level so
39	 * both the Asset Browser and Timeline panels can participate without each
40	 * owning a separate drag pipeline (`toolbar.md`: "Canvas/Timeline UI ...
41	 * should consume this one pipeline, not each define their own").
42	 */
43	function handleDragEnd(kernel: EditorKernel, event: DragEndEvent): void {
44	  const overData = event.over?.data.current as DropData | undefined;
45	  const activeData = event.active.data.current as DragData | undefined;
46	  if (!overData || overData.type !== "track" || !activeData) {
47	    return;
48	  }
49	  const ticksPerPixel = useTimelineStore.getState().zoomTicksPerPixel;
50	
51	  if (activeData.type === "asset") {
52	    const activeRect = event.active.rect.current.translated;
53	    const overRect = event.over?.rect;
54	    const pixelOffset = activeRect && overRect ? Math.max(0, activeRect.left - overRect.left) : 0;
55	    const composition = kernel.timelineEngine.requireComposition(kernel.defaultCompositionId);
56	    kernel.timelineEditor.addClipFromAsset({
57	      type: "AddClipFromAsset",
58	      payload: {
59	        trackId: overData.trackId,
60	        assetId: activeData.assetId,
61	        assetType: activeData.assetType,
62	        name: activeData.name,
63	        startTick: toTick(pixelOffset * ticksPerPixel),
64	        durationTicks: secondsToTicks(DEFAULT_CLIP_DURATION_SECONDS, composition.fps),
65	      },
66	    });
67	    return;
68	  }
69	
70	  const trackItem = kernel.timelineEngine.requireTrackItem(activeData.trackItemId);
71	  const deltaTicks = toTick(event.delta.x * ticksPerPixel);
72	  const toStartTick = toTick(Math.max(0, trackItem.startTick + deltaTicks));
73	  // A plain click still fires `onDragEnd` with zero (or near-zero) movement
74	  // — the `PointerSensor` activation distance below filters out most of
75	  // these, but this guard is a cheap, load-bearing backstop: without it, a
76	  // no-op move gets pushed onto the undo stack on every click, and Undo
77	  // then reverts that no-op instead of whatever the user actually meant.
78	  if (overData.trackId === trackItem.trackId && toStartTick === trackItem.startTick) {
79	    return;
80	  }
81	  kernel.timelineEditor.moveTrackItem({
82	    type: "MoveTrackItem",
83	    payload: { trackItemId: activeData.trackItemId, toTrackId: overData.trackId, toStartTick },
84	  });
85	}
86	
87	const GLOBAL_BINDINGS = [
88	  { key: "Delete", commandId: "DeleteSelection" },
89	  { key: "Backspace", commandId: "DeleteSelection" },
90	  { key: "Mod+Z", commandId: "Undo" },
91	  { key: "Mod+Shift+Z", commandId: "Redo" },
92	  { key: " ", commandId: "TogglePlayback" },
93	  { key: "V", commandId: "ActivateSelectTool" },
94	] as const;
95	
96	function dispatchShortcutCommand(kernel: EditorKernel, commandId: string): void {
97	  switch (commandId) {
98	    case "DeleteSelection": {
99	      const { selection, clearSelection } = useTimelineStore.getState();
100	      kernel.timelineEditor.deleteSelection({
101	        type: "DeleteSelection",
102	        payload: { trackItemIds: selection.trackItemIds },
103	      });
104	      clearSelection();
105	      return;
106	    }
107	    case "Undo":
108	      if (kernel.commandBus.canUndo) {
109	        kernel.commandBus.undo();
110	      }
111	      return;
112	    case "Redo":
113	      if (kernel.commandBus.canRedo) {
114	        kernel.commandBus.redo();
115	      }
116	      return;
117	    case "TogglePlayback":
118	      if (kernel.playback.playbackState === PlaybackState.Playing) {
119	        kernel.playback.pause();
120	      } else {
121	        kernel.playback.play();
122	      }
123	      return;
124	    case "ActivateSelectTool":
125	      kernel.toolRegistry.activate("select");
126	      useCanvasStore.getState().setActiveTool("select");
127	      return;
128	    default:
129	      return;
130	  }
131	}
132	
133	function isEditableTarget(target: EventTarget | null): boolean {
134	  if (!(target instanceof HTMLElement)) {
135	    return false;
136	  }
137	  return target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable;
138	}
