1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { useDraggable } from "@dnd-kit/core";
5	import { Plus, Search } from "lucide-react";
6	import type { IAssetCatalogEntry } from "@motion-studio/assets";
7	import { AssetType } from "@motion-studio/shared";
8	import { useEditorKernel } from "../editor-kernel-provider";
9	import { useEngineRevisionStore } from "../../state/use-engine-revision-store";
10	import { THUMBNAIL_MIME_TYPE } from "../../editor-kernel/thumbnail-generator";
11	import type { EditorKernel } from "../../editor-kernel/editor-kernel";
12	
13	const THUMBNAIL_TYPES = new Set<AssetType>([AssetType.Video, AssetType.Image]);
14	
15	/** Fetches the asset's stored thumbnail (if any) and hands back an object URL, revoked on unmount/change. */
16	function useAssetThumbnailUrl(kernel: EditorKernel, entry: IAssetCatalogEntry): string | undefined {
17	  const [url, setUrl] = useState<string | undefined>(undefined);
18	
19	  useEffect(() => {
20	    if (!THUMBNAIL_TYPES.has(entry.type)) {
21	      return;
22	    }
23	    let cancelled = false;
24	    let objectUrl: string | undefined;
25	    kernel.assetEditor.getThumbnail(entry.id).then((data) => {
26	      if (cancelled || !data) {
27	        return;
28	      }
29	      objectUrl = URL.createObjectURL(
30	        new Blob([data as unknown as BlobPart], { type: THUMBNAIL_MIME_TYPE }),
31	      );
32	      setUrl(objectUrl);
33	    });
34	    return () => {
35	      cancelled = true;
36	      if (objectUrl) {
37	        URL.revokeObjectURL(objectUrl);
38	      }
39	    };
40	  }, [kernel, entry.id, entry.type]);
41	
42	  return url;
43	}
44	
45	function AssetTile({
46	  entry,
47	  view,
48	}: {
49	  entry: IAssetCatalogEntry;
50	  view: "grid" | "list";
51	}): JSX.Element {
52	  const kernel = useEditorKernel();
53	  const thumbnailUrl = useAssetThumbnailUrl(kernel, entry);
54	  const { attributes, listeners, setNodeRef, transform } = useDraggable({
55	    id: `asset-${entry.id}`,
56	    data: { type: "asset", assetId: entry.id, assetType: entry.type, name: entry.name },
57	  });
58	
59	  const style = {
60	    transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
61	  };
62	
63	  if (view === "list") {
64	    return (
65	      <div
66	        ref={setNodeRef}
67	        {...listeners}
68	        {...attributes}
69	        style={style}
70	        className="flex cursor-grab items-center gap-2 rounded-lg border border-editor-border bg-editor-surface-raised px-2 py-1 text-xs"
71	      >
72	        {thumbnailUrl ? (
73	          <img src={thumbnailUrl} alt="" className="h-6 w-6 shrink-0 rounded object-cover" />
74	        ) : null}
75	        <span className="truncate">{entry.name}</span>
76	        <span className="text-editor-text-muted">{entry.type}</span>
77	      </div>
78	    );
79	  }
80	
81	  return (
82	    <div
83	      ref={setNodeRef}
84	      {...listeners}
85	      {...attributes}
86	      style={style}
87	      className="relative flex aspect-square cursor-grab flex-col items-center justify-center gap-0.5 overflow-hidden rounded-lg border border-editor-border bg-editor-surface-raised p-1 text-center text-[10px]"
88	    >
89	      {thumbnailUrl ? (
90	        <img src={thumbnailUrl} alt="" className="absolute inset-0 h-full w-full object-cover" />
91	      ) : null}
92	      <div
93	        className={
94	          thumbnailUrl
95	            ? "relative mt-auto flex w-full flex-col gap-0.5 bg-black/60 px-1 py-0.5"
96	            : "flex flex-col gap-0.5"
97	        }
98	      >
99	        <span className="truncate">{entry.name}</span>
100	        <span className="text-editor-text-muted">{entry.type}</span>
101	      </div>
102	    </div>
103	  );
104	}
105	
106	/**
107	 * Thin UI view over `AssetManager` (ADR-002) — no registry of its own.
108	 * `list()`/`listUnused()` are async, so this keeps local component state
109	 * refetched on `useEngineRevisionStore` bumps (`AssetImported`/
110	 * `AssetDeleted`), unlike the sync engines other panels read straight
111	 * through selectors.
112	 */
113	export function AssetBrowserPanel({ assetType }: { assetType?: AssetType }): JSX.Element {
114	  const kernel = useEditorKernel();
115	  const revision = useEngineRevisionStore((state) => state.revision);
116	  const [entries, setEntries] = useState<IAssetCatalogEntry[]>([]);
117	  const [view, setView] = useState<"grid" | "list">("grid");
118	  const [search, setSearch] = useState("");
119	  const [unusedOnly, setUnusedOnly] = useState(false);
120	  const fileInputRef = useRef<HTMLInputElement>(null);
121	
122	  useEffect(() => {
123	    let cancelled = false;
124	    const load = unusedOnly ? kernel.assetEditor.listUnused() : kernel.assetEditor.list();
125	    load.then((result) => {
126	      if (!cancelled) {
127	        setEntries(result);
128	      }
129	    });
130	    return () => {
131	      cancelled = true;
132	    };
133	  }, [kernel, revision, unusedOnly]);
134	
135	  const filtered = entries
136	    .filter((entry) => !assetType || entry.type === assetType)
137	    .filter((entry) => entry.name.toLowerCase().includes(search.toLowerCase()));
138	
139	  const handleImport = async (files: FileList | null): Promise<void> => {
140	    if (!files) {
141	      return;
142	    }
143	    for (const file of Array.from(files)) {
144	      const data = new Uint8Array(await file.arrayBuffer());
145	      try {
146	        await kernel.assetEditor.import({ fileName: file.name, mimeType: file.type, data });
147	      } catch (error) {
148	        console.error(`AssetBrowserPanel: failed to import "${file.name}"`, error);
149	      }
150	    }
151	  };
152	
153	  return (
154	    <div className="flex h-full flex-col gap-3 overflow-y-auto p-3 text-xs">
155	      <div className="flex items-center gap-2 rounded-lg border border-editor-border bg-editor-bg px-2 py-1.5">
156	        <Search className="h-3.5 w-3.5 text-editor-text-muted" aria-hidden />
157	        <input
158	          type="text"
159	          placeholder="Search assets…"
160	          value={search}
161	          onChange={(event) => setSearch(event.target.value)}
162	          className="w-full bg-transparent text-editor-text placeholder:text-editor-text-muted focus:outline-none"
163	        />
164	        <button
165	          type="button"
166	          onClick={() => fileInputRef.current?.click()}
167	          title="Import"
168	          className="shrink-0 rounded p-1 text-editor-text-muted hover:bg-editor-surface-raised"
169	        >
170	          <Plus className="h-3.5 w-3.5" aria-hidden />
171	        </button>
172	        <input
173	          ref={fileInputRef}
174	          type="file"
175	          multiple
176	          className="hidden"
177	          onChange={(event) => {
178	            void handleImport(event.target.files);
179	            event.target.value = "";
180	          }}
181	        />
182	      </div>
183	
184	      <div className="flex items-center gap-2 text-editor-text-muted">
185	        <label className="flex items-center gap-1">
186	          <input
187	            type="checkbox"
188	            checked={unusedOnly}
189	            onChange={(event) => setUnusedOnly(event.target.checked)}
190	          />
191	          Unused only
192	        </label>
193	        <button
194	          type="button"
195	          onClick={() => setView(view === "grid" ? "list" : "grid")}
196	          className="ml-auto rounded px-2 py-1 hover:bg-editor-surface-raised"
197	        >
198	          {view === "grid" ? "List" : "Grid"}
199	        </button>
200	      </div>
201	
202	      <div className={view === "grid" ? "grid grid-cols-2 gap-2" : "flex flex-col gap-1"}>
203	        {filtered.map((entry) => (
204	          <AssetTile key={entry.id} entry={entry} view={view} />
205	        ))}
206	        {filtered.length === 0 && <span className="text-editor-text-muted">No assets</span>}
207	      </div>
208	    </div>
209	  );
210	}
