34	  MIN_ZOOM_TICKS_PER_PIXEL,
35	  MAX_ZOOM_TICKS_PER_PIXEL,
36	} from "../../state/use-timeline-store";
37	import { useEngineRevisionStore } from "../../state/use-engine-revision-store";
38	import type { EditorKernel } from "../../editor-kernel/editor-kernel";
39	
40	/** ticksPerPixel change per unit of wheel `deltaY` — tuned so a mouse notch (~100) and a trackpad tick (~4-10) both feel responsive across the 1-20 zoom range. */
41	const ZOOM_WHEEL_SENSITIVITY = 0.02;
42	
43	const TRACK_ICON: Partial<Record<TrackType, LucideIcon>> = {
44	  [TrackType.Video]: Film,
45	  [TrackType.Audio]: Music2,
46	  [TrackType.Text]: Type,
47	  [TrackType.Sticker]: Sticker,
48	  [TrackType.Effect]: Wand2,
49	};
50	
51	const CHIP_STYLE: Partial<Record<TrackType, string>> = {
52	  [TrackType.Video]: "bg-chip-video-bg text-chip-video-text",
53	  [TrackType.Audio]: "bg-chip-audio-bg text-chip-audio-text",
54	  [TrackType.Text]: "bg-chip-text-bg text-chip-text-text",
55	  [TrackType.Effect]: "bg-chip-effect-bg text-chip-effect-text",
56	};
57	const DEFAULT_CHIP_STYLE = "bg-chip-default-bg text-chip-default-text";
58	
59	const NICE_SECOND_INTERVALS = [1, 2, 5, 10, 15, 30, 60, 120, 300, 600];
60	const LARGEST_RULER_INTERVAL_SECONDS =
61	  NICE_SECOND_INTERVALS[NICE_SECOND_INTERVALS.length - 1] ?? 600;
62	const MIN_RULER_MARK_SPACING_PX = 80;
63	
64	function pad(value: number): string {
65	  return value.toString().padStart(2, "0");
66	}
67	
68	function formatRulerLabel(totalSeconds: number): string {
69	  const minutes = Math.floor(totalSeconds / 60);
70	  const seconds = Math.floor(totalSeconds % 60);
71	  return `${pad(minutes)}:${pad(seconds)}`;
72	}
73	
74	function pickRulerIntervalSeconds(zoomTicksPerPixel: number, fps: number): number {
75	  const perSecond = ticksPerSecond(fps);
76	  return (
77	    NICE_SECOND_INTERVALS.find(
78	      (seconds) => (seconds * perSecond) / zoomTicksPerPixel >= MIN_RULER_MARK_SPACING_PX,
79	    ) ?? LARGEST_RULER_INTERVAL_SECONDS
80	  );
81	}
82	
83	function TimelineRuler({
84	  durationTicks,
85	  zoomTicksPerPixel,
86	  fps,
87	}: {
88	  durationTicks: Tick;
89	  zoomTicksPerPixel: number;
90	  fps: number;
91	}): JSX.Element {
92	  const intervalSeconds = pickRulerIntervalSeconds(zoomTicksPerPixel, fps);
93	  const perSecond = ticksPerSecond(fps);
94	  const intervalTicks = intervalSeconds * perSecond;
95	  const marks: number[] = [];
96	  for (let tick = 0; tick <= durationTicks; tick += intervalTicks) {
97	    marks.push(tick);
98	  }
99	
100	  return (
101	    <div className="relative h-6 shrink-0 border-b border-editor-border text-[10px] text-editor-text-muted">
102	      {marks.map((tick) => (
103	        <span key={tick} className="absolute top-1" style={{ left: tick / zoomTicksPerPixel }}>
104	          {formatRulerLabel(tick / perSecond)}
105	        </span>
106	      ))}
107	    </div>
108	  );
109	}
110	
111	function TrackHeader({ type, muted }: { type: TrackType; muted: boolean }): JSX.Element {
112	  const Icon = TRACK_ICON[type] ?? Film;
