115	  return (
116	    <div className="flex h-16 w-10 shrink-0 flex-col items-center justify-center gap-1 border-b border-r border-editor-border bg-editor-surface">
117	      <Icon className="h-3.5 w-3.5 text-editor-text-muted" aria-hidden />
118	      <MuteIcon
119	        className="h-3.5 w-3.5 text-editor-text-muted"
120	        aria-label={muted ? "Muted" : "Unmuted"}
121	      />
122	    </div>
123	  );
124	}
125	
126	function ClipBar({
127	  kernel,
128	  trackItemId,
129	  layerId,
130	  trackType,
131	  left,
132	  width,
133	  selected,
134	}: {
135	  kernel: EditorKernel;
136	  trackItemId: TrackItemId;
137	  layerId: LayerId;
138	  trackType: TrackType;
139	  left: number;
140	  width: number;
141	  selected: boolean;
142	}): JSX.Element {
143	  const { attributes, listeners, setNodeRef, transform } = useDraggable({
144	    id: `clip-${trackItemId}`,
145	    data: { type: "clip", trackItemId },
146	  });
147	  const layer = kernel.layerEngine.registry.get(layerId);
148	  const select = useTimelineStore((state) => state.select);
149	  const Icon = TRACK_ICON[trackType] ?? Film;
150	
151	  const handleClick = (event: MouseEvent): void => {
152	    event.stopPropagation();
153	    select({ layerIds: layer ? [layer.id] : [], trackItemIds: [trackItemId] });
154	  };
155	
156	  return (
157	    <button
158	      ref={setNodeRef}
159	      {...listeners}
160	      {...attributes}
161	      type="button"
162	      onClick={handleClick}
163	      className={`absolute top-1 flex h-14 items-center gap-1 overflow-hidden rounded-lg px-2 text-left text-xs ${
164	        CHIP_STYLE[trackType] ?? DEFAULT_CHIP_STYLE
165	      } ${selected ? "ring-2 ring-editor-accent" : ""}`}
166	      style={{
167	        left,
168	        width: Math.max(width, 4),
169	        transform: transform ? `translate3d(${transform.x}px, 0, 0)` : undefined,
170	      }}
171	    >
172	      <Icon className="h-3 w-3 shrink-0 opacity-70" aria-hidden />
173	      {layer?.name ?? "Clip"}
174	    </button>
175	  );
176	}
177	
178	function TrackLane({
179	  kernel,
180	  trackId,
181	  trackType,
182	  ticksPerPixel,
183	  onScrub,
184	}: {
185	  kernel: EditorKernel;
186	  trackId: TrackId;
187	  trackType: TrackType;
188	  ticksPerPixel: number;
189	  onScrub: (tick: Tick) => void;
190	}): JSX.Element {
191	  const { setNodeRef } = useDroppable({ id: `track-${trackId}`, data: { type: "track", trackId } });
192	  const selection = useTimelineStore((state) => state.selection);
193	  const items = kernel.timelineEngine.getTrackItemsSorted(trackId);
194	
195	  const handleBackgroundClick = (event: MouseEvent<HTMLDivElement>): void => {
196	    const rect = event.currentTarget.getBoundingClientRect();
197	    onScrub(toTick((event.clientX - rect.left) * ticksPerPixel));
198	  };
199	
200	  return (
201	    <div
202	      ref={setNodeRef}
203	      onClick={handleBackgroundClick}
204	      className="relative h-16 shrink-0 border-b border-editor-border"
205	    >
206	      {items.map((item) => (
207	        <ClipBar
208	          key={item.id}
209	          kernel={kernel}
210	          trackItemId={item.id}
211	          layerId={item.layerId}
212	          trackType={trackType}
213	          left={item.startTick / ticksPerPixel}
214	          width={item.durationTicks / ticksPerPixel}
215	          selected={selection.trackItemIds.includes(item.id)}
216	        />
217	      ))}
218	    </div>
219	  );
220	}
221	
222	function Playhead({
223	  trackAreaRef,
224	  currentTick,
225	  zoomTicksPerPixel,
226	  onSeek,
227	}: {
228	  trackAreaRef: RefObject<HTMLDivElement>;
229	  currentTick: Tick;
230	  zoomTicksPerPixel: number;
231	  onSeek: (tick: Tick) => void;
232	}): JSX.Element {
233	  const seekFromClientX = (clientX: number): void => {
234	    const rect = trackAreaRef.current?.getBoundingClientRect();
235	    if (!rect) {
236	      return;
237	    }
238	    onSeek(toTick(Math.max(0, (clientX - rect.left) * zoomTicksPerPixel)));
239	  };
240	
241	  const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>): void => {
242	    event.stopPropagation();
243	    event.currentTarget.setPointerCapture(event.pointerId);
244	    seekFromClientX(event.clientX);
245	  };
246	
247	  const handlePointerMove = (event: ReactPointerEvent<HTMLDivElement>): void => {
248	    if (!event.currentTarget.hasPointerCapture(event.pointerId)) {
249	      return;
250	    }
251	    seekFromClientX(event.clientX);
252	  };
253	
254	  return (
255	    <div
256	      onPointerDown={handlePointerDown}
257	      onPointerMove={handlePointerMove}
258	      className="absolute inset-y-0 z-10 w-3 -translate-x-1/2 cursor-ew-resize"
259	      style={{ left: currentTick / zoomTicksPerPixel }}
260	    >
261	      <div className="pointer-events-none absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-editor-accent" />
262	      <div className="pointer-events-none absolute left-1/2 top-0 h-3 w-3 -translate-x-1/2 rounded-sm bg-editor-accent" />
263	    </div>
264	  );
265	}
266	
267	/**
268	 * Plain full render, no windowing — PLAN.md 15.3 asks for a virtualized
269	 * track/clip view, but track/item counts in this vertical slice are small
270	 * enough that windowing would add complexity with no observable benefit
271	 * yet. Real virtualization (reusing the generic `DirtyTrackedGraph`
272	 * primitive per ADR-005, same as the Rendering Engine's Scene Graph) is
273	 * deferred until a project actually has enough clips to need it.
274	 */
275	export function TimelinePanel(): JSX.Element {
276	  const kernel = useEditorKernel();
277	  useEngineRevisionStore((state) => state.revision);
278	  const zoomTicksPerPixel = useTimelineStore((state) => state.zoomTicksPerPixel);
279	  const [currentTick, setCurrentTick] = useState(kernel.playback.currentTick);
280	  const trackAreaRef = useRef<HTMLDivElement>(null);
281	  const scrollAreaRef = useRef<HTMLDivElement>(null);
282	
283	  useEffect(() => kernel.playback.onTick(setCurrentTick), [kernel]);
284	
285	  // Ctrl+wheel (also how browsers report trackpad pinch) zooms, matching every
286	  // other timeline editor's convention — plain wheel keeps scrolling this
287	  // panel's own track list, which multi-track projects need. Attached as a
288	  // real, non-passive DOM listener rather than JSX `onWheel`: React registers
289	  // its synthetic wheel/touch listeners as passive at the root, so
290	  // `preventDefault()` inside a React onWheel handler is silently a no-op —
291	  // the browser's native pinch/ctrl+wheel page zoom fires anyway.
292	  useEffect(() => {
293	    const element = scrollAreaRef.current;
294	    if (!element) {
295	      return;
296	    }
297	    const handleWheel = (event: WheelEvent): void => {
298	      if (!event.ctrlKey) {
299	        return;
300	      }
301	      event.preventDefault();
302	      const state = useTimelineStore.getState();
303	      state.setZoom(
304	        Math.min(
305	          MAX_ZOOM_TICKS_PER_PIXEL,
306	          Math.max(
307	            MIN_ZOOM_TICKS_PER_PIXEL,
308	            state.zoomTicksPerPixel + event.deltaY * ZOOM_WHEEL_SENSITIVITY,
309	          ),
310	        ),
311	      );
312	    };
313	    element.addEventListener("wheel", handleWheel, { passive: false });
314	    return () => element.removeEventListener("wheel", handleWheel);
315	  }, []);
316	
317	  // Safari doesn't route trackpad pinch through ctrlKey `wheel` events at
318	  // all — it recognizes the pinch gesture itself and fires its own
319	  // (non-standard, WebKit-only) gesture events, which the page-zoom default
320	  // rides along on regardless of what the `wheel` listener above does.
321	  useEffect(() => {
322	    const element = scrollAreaRef.current;
323	    if (!element) {
324	      return;
325	    }
326	    const preventGesture: EventListener = (event) => event.preventDefault();
327	    element.addEventListener("gesturestart", preventGesture);
328	    element.addEventListener("gesturechange", preventGesture);
329	    element.addEventListener("gestureend", preventGesture);
330	    return () => {
331	      element.removeEventListener("gesturestart", preventGesture);
332	      element.removeEventListener("gesturechange", preventGesture);
333	      element.removeEventListener("gestureend", preventGesture);
334	    };
335	  }, []);
336	
337	  const composition = kernel.timelineEngine.requireComposition(kernel.defaultCompositionId);
338	
339	  return (
340	    <div className="flex h-64 flex-col overflow-hidden border-t border-editor-border bg-editor-bg">
341	      <div ref={scrollAreaRef} className="flex flex-1 overflow-auto">
342	        <div className="flex shrink-0 flex-col">
343	          <div className="h-6 shrink-0 border-b border-r border-editor-border bg-editor-surface" />
344	          {composition.tracks.map((trackId) => {
345	            const track = kernel.timelineEngine.requireTrack(trackId);
346	            return <TrackHeader key={trackId} type={track.type} muted={track.muted} />;
347	          })}
348	        </div>
349	        <div ref={trackAreaRef} className="relative flex-1">
350	          <TimelineRuler
351	            durationTicks={composition.durationTicks}
352	            zoomTicksPerPixel={zoomTicksPerPixel}
353	            fps={composition.fps}
354	          />
355	          <Playhead
356	            trackAreaRef={trackAreaRef}
357	            currentTick={currentTick}
358	            zoomTicksPerPixel={zoomTicksPerPixel}
359	            onSeek={(tick) => kernel.playback.seek(tick)}
360	          />
361	          <div className="flex flex-col">
362	            {composition.tracks.map((trackId) => {
363	              const track = kernel.timelineEngine.requireTrack(trackId);
364	              return (
365	                <TrackLane
366	                  key={trackId}
367	                  kernel={kernel}
368	                  trackId={trackId}
369	                  trackType={track.type}
370	                  ticksPerPixel={zoomTicksPerPixel}
371	                  onScrub={(tick) => kernel.playback.seek(tick)}
372	                />
373	              );
374	            })}
375	          </div>
376	        </div>
377	      </div>
378	    </div>
379	  );
380	}
